pipingArt=function(t){const c=icingColor(t);return softSvg(`<defs><linearGradient id="PAINTmetal" x1="0" x2="1"><stop stop-color="#8fa4b0"/><stop offset=".45" stop-color="#edf3f4"/><stop offset="1" stop-color="#8fa4b0"/></linearGradient></defs><path d="M25 17Q18 20 23 38L36 91q12 7 24-2L80 35q6-16-3-18Z" fill="url(#PAINT)" stroke="${foodBlend(c,'#896858',.35)}" stroke-width="1.5"/><path d="M24 17l-6-10 19 4 14-7 17 6 13-3-3 12Z" fill="${foodBlend(c,'#fff6eb',.3)}" stroke="${foodBlend(c,'#896858',.3)}" stroke-width="1.2"/><path d="M30 26l12 47M69 29L56 72" stroke="#fff" stroke-opacity=".32" stroke-width="5" fill="none"/><path d="M37 89q11 8 22-1l-7 23-8 6Z" fill="url(#PAINTmetal)" stroke="#91a4af" stroke-width="1.3"/><path d="M43 112l4-7 4 6" fill="none" stroke="#718995" stroke-width="1"/>`,t+' piping bag','0 0 100 120',[foodBlend(c,'#fff7eb',.25),foodBlend(c,'#8e6558',.15)])};
toppingArt=function(t){let b='',p=['#f4b5bd','#d98196'];if(t==='Strawberries')b=`<path d="M20 38C24 18 43 23 50 27C63 20 79 23 82 40C83 60 63 82 51 92C36 83 18 59 20 38Z" fill="url(#PAINT)" stroke="#be7186" stroke-width="1.6"/><path d="M48 28L34 16l15 5 9-10-2 13 17-2-14 10-12 2-19-8Z" fill="#9cb888" stroke="#829c72" stroke-width="1"/><path d="M31 38q-5 11 2 22" stroke="#ffd5d6" stroke-width="5" fill="none" opacity=".55"/>${[[39,41],[59,40],[31,54],[50,56],[67,54],[43,70],[58,70],[51,82]].map(([x,y])=>`<ellipse cx="${x}" cy="${y}" rx="1.5" ry="2.8" fill="#fff0bc" transform="rotate(12 ${x} ${y})"/>`).join('')}`;else if(t==='Chocolate chips'){p=['#bd8c6b','#73503e'];b='<path d="M18 72C18 52 39 47 47 31Q53 20 49 10C69 23 88 48 85 69Q85 88 54 90Q23 91 18 72Z" fill="url(#PAINT)" stroke="#72513e" stroke-width="1.5"/><path d="M31 65q5-13 21-21" stroke="#d0a287" stroke-width="5" stroke-linecap="round" fill="none" opacity=".65"/><ellipse cx="51" cy="79" rx="22" ry="5" fill="#66432e" opacity=".15"/>'}else if(t==='Flowers'){p=['#f4d6e6','#c89fbb'];b=`${[0,72,144,216,288].map(a=>`<ellipse cx="50" cy="29" rx="14" ry="22" fill="url(#PAINT)" stroke="#b991a9" stroke-width="1" transform="rotate(${a} 50 50)"/>`).join('')}<circle cx="50" cy="50" r="13" fill="#eed389"/><circle cx="47" cy="46" r="5" fill="#fff0ba" opacity=".5"/>`}else{p=['#fff4e0','#e8d2b4'];b=[[23,25,'#df9bb5'],[56,19,'#aac4d1'],[42,48,'#e5c276'],[73,58,'#b7adcf'],[22,73,'#adc193'],[63,80,'#dfa88a']].map(([x,y,c],i)=>`<path d="M${x} ${y}l${i%2?13:6} ${i%2?7:14}" stroke="${c}" stroke-width="7" stroke-linecap="round"/>`).join('')}return softSvg(b,t,'0 0 100 100',p)};
const bowlBeforePolish=bowlArt;bowlArt=function(mixing=false){let svg=bowlBeforePolish(mixing),id='bowlglaze'+illustrationId++;const defs=`<defs><linearGradient id="${id}" x1="0" y1="0" x2=".8" y2="1"><stop stop-color="#d9e5ec"/><stop offset=".55" stop-color="#b5cbdc"/><stop offset="1" stop-color="#a0bace"/></linearGradient></defs>`;return svg.replace(/(<svg[^>]*>)/,'$1'+defs).replace('fill="#b5cbdc"',`fill="url(#${id})"`)};
